Translate the following GNU C++14 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
using ull = unsigned long long;
const ull INF = 17446744073709551616ull;
ull mod,n,k;
ull fac[250005], inv[250005], dp[18][250005];

inline ull qpow(ull a, ull b) {
    ull res = 1;
    while (b) {
        if (b & 1ULL) res = res * a % mod;
        a = a * a % mod;
        b >>= 1ULL;
    }
    return res;
}

inline ull C(int a, int b) {
    return fac[a] * inv[b] % mod * inv[a-b] % mod;
}

ull calc() {
    int i, j, l;
    fac[0] = 1ULL;
    for (i = 1; i <= (int)n; ++i) fac[i] = fac[i-1] * (ull)i % mod;
    inv[(int)n] = qpow(fac[(int)n], mod - 2ULL);
    for (i = (int)n - 1; i >= 0; --i) inv[i] = inv[i+1] * (ull)(i+1) % mod;
    for (i = 1; i <= (int)n; ++i) dp[1][i] = inv[i];

    ull ans = dp[1][(int)n] * C((int)k, 1) % mod;
    int t = min(17, (int)k);
    for (i = 2; i <= t; ++i) {
        for (j = (int)n; j; j = (j-1) & (int)n) {
            if (!dp[i-1][j]) continue;
            int r = ((int)n) ^ j;
            for (l = r; l; l = (l-1) & r) {
                dp[i][j+l] += dp[i-1][j] * inv[l];
                if (dp[i][j+l] > INF) dp[i][j+l] %= mod;
            }
        }
        for (j = (int)n; j; j = (j-1) & (int)n) dp[i][j] %= mod;
        ans = (ans + dp[i][(int)n] * C((int)k, i)) % mod;
    }
    return ans * fac[(int)n] % mod;
}

int main() {
    cin >> n >> k >> mod;
    ull ans = qpow(k, n);
    if (n % 2 == 0) ans = (ans - calc() + mod) % mod;
    cout << ans << endl;
    return 0;
}
